import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.D7xI0JV8.js";const h=JSON.parse('{"title":"Trade Desk (/trade)","description":"","frontmatter":{},"headers":[],"relativePath":"trade-desk.md","filePath":"trade-desk.md"}'),r={name:"trade-desk.md"};function l(s,e,c,d,n,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="trade-desk-trade" tabindex="-1">Trade Desk (<code>/trade</code>) <a class="header-anchor" href="#trade-desk-trade" aria-label="Permalink to &quot;Trade Desk (`/trade`)&quot;">​</a></h1><p>Trade Desk is the execution surface where opportunities are screened by the <a href="/docs/zkml-circuits.html">13-circuit zkML bundle</a> before any action is available for execution. No circuit pass means no execution path is surfaced. Every opportunity that appears in the Trade Desk has passed the relevant screening gates — risk score, anomaly detection, strategy integrity, and whatever other circuits the user&#39;s policy posture requires.</p><h2 id="where-opportunities-and-adapters-are" tabindex="-1">Where Opportunities And Adapters Are <a class="header-anchor" href="#where-opportunities-and-adapters-are" aria-label="Permalink to &quot;Where Opportunities And Adapters Are&quot;">​</a></h2><h3 id="opportunity-stream-list" tabindex="-1">Opportunity stream/list <a class="header-anchor" href="#opportunity-stream-list" aria-label="Permalink to &quot;Opportunity stream/list&quot;">​</a></h3><ul><li>Displays categories such as <code>swap</code>, <code>lp</code>, <code>lending</code>, <code>staking</code>, and related routes.</li><li>Supports sorting/filtering by yield, risk, confidence, and strategy fit.</li><li>Selecting an item should open its execution workspace.</li></ul><h3 id="execution-workspace" tabindex="-1">Execution workspace <a class="header-anchor" href="#execution-workspace" aria-label="Permalink to &quot;Execution workspace&quot;">​</a></h3><ul><li>Shows adapter choices for the selected opportunity.</li><li>Shows privacy mode and gate status.</li><li>Shows simulation controls and execution action.</li></ul><p>If adapter metadata exists, you should see explicit route choices. If not, system falls back to default builder logic.</p><h2 id="adapter-families-you-should-expect" tabindex="-1">Adapter Families You Should Expect <a class="header-anchor" href="#adapter-families-you-should-expect" aria-label="Permalink to &quot;Adapter Families You Should Expect&quot;">​</a></h2><ul><li><code>ekubo</code> (swap and LP flows)</li><li><code>limit_orders</code></li><li><code>lending</code></li><li><code>staking</code></li><li><code>dca</code></li><li>privacy-route variants when policy/flow requires them</li></ul><h2 id="standard-execution-workflow" tabindex="-1">Standard Execution Workflow <a class="header-anchor" href="#standard-execution-workflow" aria-label="Permalink to &quot;Standard Execution Workflow&quot;">​</a></h2><ol><li>Select opportunity from the stream.</li><li>Choose adapter route.</li><li>Confirm privacy mode and gate state.</li><li>Simulate.</li></ol><ul><li>Check price impact, fees, and expected output.</li><li>Set slippage explicitly for swap routes.</li></ul><ol start="5"><li>Execute via wallet signature.</li><li>Capture tx hash/receipt and verify refresh.</li></ol><h2 id="swap-workflow-critical" tabindex="-1">Swap Workflow (Critical) <a class="header-anchor" href="#swap-workflow-critical" aria-label="Permalink to &quot;Swap Workflow (Critical)&quot;">​</a></h2><ol><li>Choose swap opportunity.</li><li>Set slippage (<code>0.5%</code>, <code>1%</code>, <code>2%</code> or equivalent control).</li><li>Run simulation first.</li><li>Execute only if output and impact are acceptable.</li></ol><h2 id="if-something-looks-wrong" tabindex="-1">If Something Looks Wrong <a class="header-anchor" href="#if-something-looks-wrong" aria-label="Permalink to &quot;If Something Looks Wrong&quot;">​</a></h2><ul><li>No opportunities: check market feed connectivity and refresh state.</li><li>No adapter choices: confirm opportunity includes adapter metadata, then check fallback route behavior.</li><li>Simulation succeeds but execution fails: check gate mismatch, wallet signing errors, or stale calldata.</li></ul><p>Next: <a href="/docs/capital-os.html">Capital OS</a> | <a href="/docs/how-systems-work.html">How Systems Work</a> | <a href="/docs/api-overview.html">API Overview</a></p>',19)])])}const f=a(r,[["render",l]]);export{h as __pageData,f as default};
